  "shortcuts.interactiveHelp": "Vklopi ali izklopi interaktivno pomoč",
  "installHint.chromium": "Namesti z ikono na desni strani naslovne vrstice ali v meniju brskalnika pod »Namesti kot aplikacijo«.",
  "installHint.safariMac": "V Safariju: meni File → »Add to Dock«.",
  "installHint.ios": "V Safariju: ikona Share → »Add to Home Screen«.",
  "installHint.firefox": "Firefox ne more namestiti aplikacij – layerling se tu še vedno zažene brez povezave v zavihku.",
  "welcome.moreLanguagesTitle": "Tvoj jezik",
  "welcome.moreLanguagesBody": "program in njegov priročnik govorita angleško, nemško in še 17 drugih jezikov; seznam jezikov je čisto zgoraj desno in v nastavitvah na začetni strani.",
  "welcome.moreOfflineTitle": "Deluje brez povezave",
  "welcome.moreOfflineBody": "layerling deluje tudi brez interneta – projekti ostanejo v tvojem računalniku.",
  "welcome.moreAiTitle": "Gradnja z umetno inteligenco",
  "welcome.moreAiBody": "prek vmesnika MCP lahko pomočnik z umetno inteligenco ustvarja in ureja oblike.",
  "welcome.morePointsTitle": "Referenčne točke",
  "welcome.moreSearchTitle": "Iskanje ukazov",
  "welcome.moreSimplifyTitle": "Poenostavitev mrež",
  "welcome.moreSimplifyBody": "Uvožena mreža z zelo veliko trikotniki se zmanjša na delček, s pogledom pred in po ter drsnikom – tako rezanje, združevanje in vlečenje ostanejo tekoči.",
  "welcome.moreHistoryTitle": "Zgodovina",
  "welcome.moreLookTitle": "Videz po tvoje",
  "welcome.moreLookBody": "Ozadje in delovno ravnino, robne črte na vsakem telesu, barve skic ter kontrast in moč senc osvetlitve nastaviš v nastavitvah – na primer, da se temna telesa ne zlijejo med seboj.",
  "welcome.moreHistoryBody": "s drsnikom si oglej katero koli prejšnje stanje projekta, ne da bi karkoli spremenil – izvozi to stanje ali iz njega začni nov projekt.",
  "welcome.moreSearchBody": "Pritisni Ctrl+K in vnesi ime orodja, oblike ali ukaza, da skočiš naravnost nanj – v angleščini ali nemščini, ob vsakem s prikazano bližnjico. Telesa v projektu se najdejo tudi po imenu.",
  "welcome.morePointsBody": "z desnim klikom na telo označi njegovo središče, oglišča ali sredine robov s točkami, ki se ne natisnejo in na katere se oblike pripenjajo – nato postavi luknjo natančno na središče drugega dela.",
  "welcome.videosTitle": "Videi o programu layerling",
  "welcome.videosHint": "Jih ustvarjajo drugi, ne ta projekt. Povezave odprejo YouTube v novem zavihku; dokler ne klikneš, se od tam ne naloži nič.",
  "welcome.help": "V urejevalniku skupina Pomoč vsebuje kratek vodnik in seznam vseh bližnjic. V nogi strani »Prijava napake« shrani projekt z vsem, kar je potrebno za prijavo na forumu ali na GitHubu.",
  "welcome.guideLink": "Preberi celoten uporabniški priročnik s slikami",
  "welcome.guideUrl": "/navodila/index.html",
