  "edge.revertOffset": "Odmik ({size} mm)",
  "historyStep.offsetOne": "Odmaknjeno: {name}",
  "historyStep.offsetMany": "Odmaknjenih objektov: {count}",
  "guide.edges.offset": "Odmik premakne vsako ploskev telesa za isto razdaljo, navzven ali navznoter. Povečaj kopijo in jo obdrži kot luknjo, da dobiš zračnost nasedanja, ali zmanjšaj telo za čep, ki mora v luknjo. Telesa, ki so samo trikotniška mreža, pogosto ni mogoče odmakniti.",
  "edge.revertSurfaceTexture": "Površinska tekstura (globina {size} mm)",
  "deleteFace.title": "Izbriši ploskev",
  "deleteFace.subtitle": "Okoliške ploskve zaprejo vrzel",
  "deleteFace.help": "Klikni ploskve, ki naj izginejo; ob ponovnem kliku ploskev spet odstraniš iz izbire. Okoliške ploskve rastejo, dokler se vrzel ne zapre: zaokrožitev, luknja ali izboklina izgine, telo pa ostane natančno.",
  "deleteFace.preparing": "Branje ploskev …",
  "deleteFace.countNone": "Nobena ploskev še ni izbrana",
  "deleteFace.countOne": "Izbrana 1 ploskev",
  "deleteFace.countMany": "Izbranih ploskev: {count}",
  "deleteFace.apply": "Izbriši",
  "deleteFace.working": "Brisanje ploskev …",
  "deleteFace.cancel": "Prekliči brisanje ploskev",
  "deleteFace.errorUnchanged": "Teh ploskev ni mogoče izbrisati: okoliške ploskve ne zaprejo vrzeli. Izberi vse ploskve tistega, kar naj izgine, na primer vse ploskve zaokrožitve ali celo steno luknje, in nobene ploskve samega telesa.",
  "deleteFace.errorMesh": "To telo nima natančnih ploskev za brisanje: layerling ga hrani kot mrežo, tako kot uvožen STL, OBJ ali 3MF, razdeljeno, okoli valja ovito ali poenostavljeno telo ali zelo podrobno obliko, na primer dolgo besedilo. Del, uvožen kot STEP, ima natančne ploskve.",
  "deleteFace.errorResized": "Temu telesu se je spremenila velikost ob vklopljeni možnosti »Ohrani velikost roba pri spreminjanju velikosti«, zato se njegove natančne ploskve ne ujemajo več z njo. Razveljavi spremembo velikosti, izbriši ploskve in nato znova spremeni velikost.",
  "deleteFace.errorProjectChanged": "Objekt ali projekt se je med brisanjem ploskev spremenil; poskusi znova.",
  "deleteFace.errorFailed": "Ploskev ni bilo mogoče izbrisati. Izberi druge ploskve.",
  "deleteFace.errorNoFaces": "Ploskev tega telesa ni bilo mogoče prebrati. Zapri orodje in ga znova odpri.",
  "deleteFace.errorTooSlow": "Brisanje teh ploskev je trajalo predolgo in je bilo po 45 sekundah ustavljeno; nič se ni spremenilo. Jedro CAD na tem delu ne zmore obdelati teh ploskev: izberi druge ploskve ali manj ploskev.",
  "status.facesDeletedOne": "Izbrisana 1 ploskev",
