  "export.step.note": "Ohrani kvadre, valje, krogle in stožce kot natančno CAD geometrijo, prav tako vse z zaokroženimi ali posnetimi robovi in telesa, uvožena kot STEP. Navoji, vzmeti in zobniki se izvozijo kot natančno telo. Zvite oblike in uvožene mreže so na primer onkraj zmožnosti STEP – te izvozi kot STL.",
  "export.svg.description": "Vektor pogleda od zgoraj",
