  "export.svg.noteEdges": "Izvozi robove, vidne od zgoraj, kot črte v milimetrih, vsako telo v svoji barvi: obrise, luknje, žepe in gravure, vsako površino sklenjeno, za lasersko graviranje in risalnike.",
