  "export.historyNone": "Brez",
  "newVersion.title": "Nova različica layerlinga je pripravljena",
  "newVersion.body": "Ta stran se je zagnala z različico {current}; strežnik ima zdaj {latest}. Naloži znova za preklop – tvoji načrti ostanejo v tem brskalniku, tisti, ki ga imaš odprtega, se najprej shrani in se vrne točno takšen, kot je.",
  "newVersion.reload": "Shrani in naloži znova",
  "newVersion.later": "Pozneje",
  "welcome.moreAttachmentsTitle": "Datoteke v načrtu",
  "welcome.moreAttachmentsBody": "zapiski in seznami kot .md ali .txt, fotografija natisnjenega dela (.png, .jpg, .webp) ali podatkovni list kot PDF ostanejo v načrtu in potujejo z datoteko .lyl. Oko pokaže besedilo ali sliko v oknu; PDF se prenese.",
  "welcome.moreSaveTitle": "Shrani v svojo mapo",
  "welcome.moreSaveBody": "v Chromu in Edgeu mapo in ime izbereš sam, Ctrl+S pa načrt spet shrani v isto datoteko – datoteka, ki si jo odprl, se nadomesti na mestu. Drugi brskalniki jo prenesejo.",
  "guide.shapes.text": "Besedilo je lastna oblika: izberi pisavo (tudi svojo), ukrivi ga po loku, pod Polnilo pa zgradi obrise, silhueto ali plast Širše. Naredi plasti ga spremeni v napis z imenom za večbarvni tisk, Simbolna oznaka v knjižnici oblik pa isto naredi za simbol SVG.",
  "guide.edges.hollow": "Izdolbi telo spremeni v lupino s stenami enakomerne debeline: izberi steno, katere strani ostanejo odprte (katera koli ali nobena) in ali so notranji robovi zaobljeni ali ostri. Izdolbeno telo je mogoče spet spremeniti kot zaokrožitev.",
  "guide.edges.deleteFace": "Izbriši ploskev odstrani zaokrožitev, luknjo ali izboklino: klikni vse njene ploskve, nato Izbriši. Okoliške ploskve zaprejo vrzel, telo pa ostane natančno.",
  "guide.sketch.construction": "Gradbena črta je črtkana in nikoli ni del obrisa: vklopi jo pod Riši ali pa črto spremeni vanjo. Nove točke se zaskočijo tja, kjer seka drugo črto – tako postaviš vogal na sredino ali na določeno razdaljo.",
  "shortcuts.save": "Shrani načrt v njegovo datoteko",
  "historyView.delete": "Izbriši zgodovino",
  "historyView.deleteHint": "Za vedno odstrani vse prejšnje korake; načrt ohrani trenutno stanje",
  "historyView.deleteNothing": "Ni prejšnjih korakov, ki bi jih bilo mogoče izbrisati",
  "historyView.deleteTitle": "Izbrišem vso zgodovino?",
  "historyView.deleteBody": "Načrt ostane točno takšen, kot je zdaj. Vsi prejšnji koraki se za vedno odstranijo – Razveljavi in ta pogled se ne moreta več vrniti nazaj, datoteka, shranjena pozneje, pa ne nosi zgodovine.",
  "historyView.deleteConfirm": "Izbriši zgodovino",
