  "newVersion.titleMismatch": "Del te strani je iz druge različice",
  "newVersion.bodyMismatch": "Datoteka, ki jo je stran naložila pozneje, ne ustreza ostalim, običajno po posodobitvi ali pri shranjeni kopiji starejše različice. Naloži znova za popravek – tvoji načrti ostanejo v tem brskalniku, tisti, ki ga imaš odprtega, se najprej shrani in se vrne točno takšen, kot je.",
